const updateFeedEntriesRevision = `-- name: UpdateFeedEntriesRevision :execrows
UPDATE feed_entries SET language = ?1, revision_seq = ?2
WHERE status_id = ?3 AND revision_seq < ?2
`

type UpdateFeedEntriesRevisionParams struct {
	Language    string
	RevisionSeq int64
	StatusID    string
}

// UpdateFeedEntriesRevision moves the entries of a status (the post and its boosts) to a
// newer revision; an older or repeated revision changes nothing.
func (q *Queries) UpdateFeedEntriesRevision(ctx context.Context, arg UpdateFeedEntriesRevisionParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, updateFeedEntriesRevision, arg.Language, arg.RevisionSeq, arg.StatusID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

const upsertFeedAuthorRestriction = `-- name: UpsertFeedAuthorRestriction :exec
INSERT INTO feed_author_restrictions (account_id, restriction, effective_until) VALUES (?, ?, ?)
ON CONFLICT (account_id, restriction) DO UPDATE SET effective_until = excluded.effective_until
`

type UpsertFeedAuthorRestrictionParams struct {
	AccountID      string
	Restriction    string
	EffectiveUntil sql.NullInt64
}

func (q *Queries) UpsertFeedAuthorRestriction(ctx context.Context, arg UpsertFeedAuthorRestrictionParams) error {
	_, err := q.db.ExecContext(ctx, upsertFeedAuthorRestriction, arg.AccountID, arg.Restriction, arg.EffectiveUntil)
	return err
}

